// Keeps the built game in step with its sources (2026-11-21). The world, the classes and the sprites are generated by the
// Tools/ scripts and only reach the scenes / GameAssets through Tools > Game > Build Game; when that step is forgotten the
// game shows the old map and the class select shows empty cards. After every script reload (opening the project, coming
// back to Unity after a change) this checks whether any source is newer than the built world and offers to rebuild.
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace WoodsGame.EditorTools
{
    [InitializeOnLoad]
    static class AutoRebuild
    {
        const string Scene = "Assets/Game/Scenes/World.unity";
        const string AssetsFile = "Assets/Game/Resources/GameAssets.asset";
        static bool _asked;

        static AutoRebuild()
        {
            EditorApplication.delayCall += Check;
            EditorApplication.playModeStateChanged += OnPlayMode;
        }

        /// <summary>Pressing Play with an out-of-date build: build first, then play (nobody plays the old map again).</summary>
        static void OnPlayMode(PlayModeStateChange st)
        {
            if (st != PlayModeStateChange.ExitingEditMode || Application.isBatchMode || !Stale()) return;
            EditorApplication.isPlaying = false;
            EditorApplication.delayCall += () =>
            {
                Debug.Log("[AutoRebuild] the game was out of date: building before Play");
                GameBuilder.BuildGame();
                UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Game/Scenes/MainMenu.unity");
                EditorApplication.delayCall += () => EditorApplication.isPlaying = true;
            };
        }

        static bool Stale()
        {
            if (!File.Exists(Scene) || !File.Exists(AssetsFile)) return false;
            var built = new[] { File.GetLastWriteTimeUtc(Scene), File.GetLastWriteTimeUtc(AssetsFile) }.Min();
            var newest = new[]
            {
                Newest("Assets/Game/Levels", "*.txt"), Newest("Assets/Game/Levels", "*.json"),
                Newest("Assets/Art/Characters", "*_animations.json"), Newest("Assets/Art/World/Ground", "*.png"),
                File.GetLastWriteTimeUtc("Assets/Game/Scripts/RPG/KnightClass.cs"), Newest("Assets/Game/Editor", "*.cs"),
            }.Max();
            return newest > built.AddSeconds(5);
        }

        static DateTime Newest(string dir, string pattern)
        {
            if (!Directory.Exists(dir)) return DateTime.MinValue;
            return Directory.EnumerateFiles(dir, pattern, SearchOption.AllDirectories)
                .Where(f => !f.EndsWith(".meta")).Select(File.GetLastWriteTimeUtc).DefaultIfEmpty(DateTime.MinValue).Max();
        }

        static void Check()
        {
            if (_asked || Application.isBatchMode || EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling) return;
            if (!File.Exists(Scene) || !File.Exists(AssetsFile)) return;
            var built = new[] { File.GetLastWriteTimeUtc(Scene), File.GetLastWriteTimeUtc(AssetsFile) }.Min();
            var sources = new[]
            {
                Newest("Assets/Game/Levels", "*.txt"),
                Newest("Assets/Game/Levels", "*.json"),
                Newest("Assets/Art/Characters", "*_animations.json"),
                Newest("Assets/Art/World/Ground", "*.png"),
                File.GetLastWriteTimeUtc("Assets/Game/Scripts/RPG/KnightClass.cs"),
                Newest("Assets/Game/Editor", "*.cs"),
            };
            var newest = sources.Max();
            if (newest <= built.AddSeconds(5)) return;
            _asked = true;
            if (EditorUtility.DisplayDialog("El juego está desactualizado",
                    "El mapa, las clases o los sprites cambiaron después de la última construcción, así que el juego todavía " +
                    "muestra la versión anterior.\n\n¿Reconstruir ahora? (Tools ▸ Game ▸ Build Game, tarda unos minutos)",
                    "Reconstruir ahora", "Más tarde"))
                GameBuilder.BuildGame();
        }
    }
}
